'use strict';
const menu=document.querySelector('.menu-toggle'),nav=document.querySelector('#nav-links');
menu.addEventListener('click',()=>{const open=menu.getAttribute('aria-expanded')!=='true';menu.setAttribute('aria-expanded',String(open));menu.setAttribute('aria-label',open?'메뉴 닫기':'메뉴 열기');nav.classList.toggle('open',open)});
nav.querySelectorAll('a').forEach(a=>a.addEventListener('click',()=>{menu.setAttribute('aria-expanded','false');menu.setAttribute('aria-label','메뉴 열기');nav.classList.remove('open')}));
let service=0;const tabs=[...document.querySelectorAll('[data-service]')];
function setService(index,focus=false){service=index;tabs.forEach((t,i)=>{const on=i===index;t.setAttribute('aria-selected',String(on));t.tabIndex=on?0:-1;t.querySelector('img').src='assets/'+(on?'9f8f7.svg':'cb2e4.svg');document.querySelector('#'+t.getAttribute('aria-controls')).hidden=!on});document.querySelector('#service-count').textContent=index?'02 / 02':'01 / 02';if(focus)tabs[index].focus()}
tabs.forEach((t,i)=>{t.addEventListener('click',()=>setService(i));t.addEventListener('keydown',e=>{if(['ArrowLeft','ArrowRight','Home','End'].includes(e.key)){e.preventDefault();setService(e.key==='Home'?0:e.key==='End'?1:1-service,true)}})});
document.querySelectorAll('.service-prev,.service-next').forEach(b=>b.addEventListener('click',()=>setService(1-service)));
document.querySelectorAll('[data-select-service]').forEach(a=>a.addEventListener('click',()=>setService(Number(a.dataset.selectService))));
document.querySelectorAll('[data-interest]').forEach(a=>a.addEventListener('click',()=>{document.querySelectorAll('[name=interest]').forEach(i=>i.checked=i.value===a.dataset.interest)}));
let slide=0;const dots=[...document.querySelectorAll('[data-slide]')];function setSlide(i){slide=i;document.querySelector('#banner-title').innerHTML=i?'해외 판매를 준비한다면<br>해외 인증 상담':'국내 판매를 준비한다면<br>KC인증 상담';document.querySelector('#banner-link').textContent=i?'해외 인증 안내 보기 →':'KC인증 안내 보기 →';dots.forEach((b,j)=>{b.setAttribute('aria-pressed',String(i===j));b.querySelector('img').src='assets/'+(i===j?'4f45f.svg':'b5424.svg')})}
dots.forEach((b,i)=>b.addEventListener('click',()=>setSlide(i)));document.querySelector('#banner-link').addEventListener('click',()=>setService(slide));
const dialog=document.querySelector('#privacy');document.querySelectorAll('.privacy-link').forEach(b=>b.addEventListener('click',()=>dialog.showModal()));document.querySelectorAll('.dialog-close,.dialog-done').forEach(b=>b.addEventListener('click',()=>dialog.close()));dialog.addEventListener('click',e=>{if(e.target===dialog){const r=dialog.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)dialog.close()}});
document.querySelector('#consultation').addEventListener('submit',e=>{e.preventDefault();const s=document.querySelector('#form-status');s.hidden=false;s.textContent='입력 항목을 확인했습니다. 현재는 디자인 미리보기로, 상담 내용은 실제 전송되지 않았습니다.';s.scrollIntoView({block:'nearest'})});
